"""Measure samples generated by the RTL simulation (not a host sound model)."""
import json,math,wave
from pathlib import Path
import numpy as np
out=Path(__file__).resolve().parents[1]/'test-output'
data=np.loadtxt(out/'engine_samples.csv',delimiter=',',dtype=np.int32)
mono=data[data[:,0]==0,1].astype(float)
settled=mono[6000:]
spec=np.abs(np.fft.rfft(settled*np.hanning(len(settled))))
freq=np.fft.rfftfreq(len(settled),1/48000)
peak_hz=float(freq[np.argmax(spec[1:])+1])
assert abs(peak_hz-440)<3,(peak_hz,'A4 pitch')
chord=data[data[:,0]==1,1].astype(float)[6000:]
cs=np.abs(np.fft.rfft(chord*np.hanning(len(chord))))
ratios={}
for n in [60,62,64,65,67,69,71,72]:
    hz=440*2**((n-69)/12)
    strength=float(cs[np.abs(freq-hz)<4].max())
    ratios[n]=round(strength/max(1,float(np.median(cs))),1)
    assert ratios[n]>100,(n,'missing chord fundamental',ratios[n])
assert np.max(np.abs(data[:,1]))<32767,'Clipping'
assert np.max(np.abs(data[data[:,0]==2,1][-1000:]))==0,'Release tail not silent'
assert np.max(np.abs(data[data[:,0]==3,1][-1000:]))==0,'Pluck tail not silent'
report={'sample_rate':48000,'a4_hz_fft':round(peak_hz,3),'peak_abs':int(np.max(np.abs(data[:,1]))),
        'eight_note_spectral_ratios':ratios,'release_silent':True,'pluck_silent':True}
(out/'audio_analysis.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
with wave.open(str(out/'rtl_demo.wav'),'wb') as w:
    w.setnchannels(2);w.setsampwidth(2);w.setframerate(48000)
    w.writeframes(np.repeat(data[:,1].astype('<i2')[:,None],2,axis=1).tobytes())
print('PASS RTL audio analysis:',json.dumps(report))
